    center * 0.24 +
    (left + right + up + down) * 0.10 +
    (upLeft + upRight + downLeft + downRight) * 0.06 +
    (left2 + right2 + up2 + down2) * 0.03;
  return mix(baseSmoothed, wideBlurred, wideMix);
